local CoWait = CS.Engine.Lib.CoWait
local util = require 'XLua.util'
local cs_coroutine = import('XLua.cs_coroutine')
local WaitForSeconds = CS.UnityEngine.WaitForSeconds

local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
local FishingUtils = import('Game.UI.Fishing.FishingUtils')
local fishingComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FishingComponent)
local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)

---@class UIFishPoolHangUpQueueNode
---@field ImgBtnFrame                   	Game.Native.Common.UISwitchImage        
---@field TxtNum                        	UnityEngine.RectTransform               
---@field BtnQuest                      	UnityEngine.RectTransform                                            
local UIFishPoolHangUpQueueNode = Class("UIFishPoolHangUpQueueNode")
function UIFishPoolHangUpQueueNode:__init() 
    self._queueId = nil
    self._queueDojo = nil
    self._cb = nil
end

function UIFishPoolHangUpQueueNode:__delete()
    self._queueId = nil
    self._queueDojo = nil
    self._cb = nil
end

function UIFishPoolHangUpQueueNode:Awake()    
end

function UIFishPoolHangUpQueueNode:Start()
    self.EventFishHangUpTimeDown = Events.AddListener(Constants.EventNames.FishHangUpTimeDown, Bind(self, self.OnFishHangUpTimeDown))
    SetButtonAction(self.Root, Bind(self, self.OnBtnChooseQueue))
    --SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnEnterFishPlace))
end

function UIFishPoolHangUpQueueNode:Refresh(queueId, cb)
    if not queueId then
        return
    end
    self._queueId = queueId
    self._queueDojo = fishingComponent:GetHangUpDojoByQueueId(self._queueId)
    self._cb = cb

    self:FillSelf()
end

function UIFishPoolHangUpQueueNode:FillSelf()
    CfUtils.FillText(self.unLockEntrustId, self._queueId)    
    self:FillCards()
    self:FillTaskInfo()
end

function UIFishPoolHangUpQueueNode:FillTaskInfo()
    if self._queueDojo then
        local isHaveTask = FishingUtils.IsHangeUpQueueHasTask(self._queueId)
        --有任务
        if isHaveTask then
            local isFinish = FishingUtils.IsHangeUpQueueTaskFinish(self._queueId)
            local vo = FishingUtils.GetFishingPlaceVo(self._queueDojo.placeId)
            if vo then
                CfUtils.FillText(self.TxtName, vo.name)
            end
            CfUtils.FillText(self.TxtTimeNumber, CfUtils.GetTimeHMS2(self._queueDojo.remainTime))
            KTool.SetActive(self.btns, true)
            KTool.SetActive(self.cancel, isHaveTask and not isFinish)
            KTool.SetActive(self.Finish, isFinish)
        else
            CfUtils.FillText(self.TxtName, localize("空闲队列"))
            KTool.SetActive(self.btns, false)
        end
    else
        CfUtils.FillText(self.TxtName, localize("未解锁"))
        KTool.SetActive(self.btns, false)
    end

    local isUnlock = FishingUtils.IsUnlockQueueById(self._queueId)
    if isUnlock then
        CfUtils.FillText(self.TxtName, localize("队列")..self._queueId)
    else
        CfUtils.FillText(self.TxtName, localize("未解锁"))
    end
end

function UIFishPoolHangUpQueueNode:FillCards(bufferData)
    local cardsData = {}
    if self._queueDojo then
        cardsData = CfUtils.Split(checkString(self._queueDojo.cards), ",")
    end
    local maxNum = FishingUtils.GetFishTeamMaxNum(self._queueId)
    if maxNum < 1 then
        return
    end

    for i = 1, maxNum do
        local go = self.teamInfo.transform:Find("card"..i)
        if not go then
            go = CfUtils.InstantiateGo(self.card, self.teamInfo)
            go.name = "card"..i
        end

        self:FillCard(go, cardsData[i], i, bufferData)
    end
end

--绘制卡牌数据
function UIFishPoolHangUpQueueNode:FillCard(go, cardId, ind, bufferData)
    KTool.SetActive(go, true)

    cardId = checkNumber(cardId)
    local bgGo = go.transform:Find("BtnClick")
    local cardParGo = go.transform:Find("Unlock/cardPar")
    SetButtonAction(bgGo, Bind(self, self.OnBtnChooseCard, ind))
    local isUnlock, errStr = FishingUtils.IsUnlockTeamPosByQueueAndCol(self._queueId, ind)
    KTool.SetActive(go.transform:Find("Unlock"), isUnlock)    
    KTool.SetActive(go.transform:Find("Lock"), not isUnlock)    

    --解锁
    if isUnlock then
        local isHaveCard = (checkNumber(cardId) ~= 0)
        KTool.SetActive(cardParGo, isHaveCard)
        if isHaveCard then
            local cardDojo = cardComp:GetCardById(checkString(cardId))
            CfUtils.RefeshCommonSmallHeroGo(cardParGo.transform:Find("CommonSmallHeadNode"), cardDojo, Vector3(0.64, 0.64, 0.64), function()
                self:OnBtnChooseCard(ind)
            end)
    
            local hpImageGo = cardParGo.transform:Find("HpStrength/HpBg/Hp"):GetComponent(typeof(CS.UnityEngine.UI.Image))
            local textHpGo = cardParGo.transform:Find("HpStrength/HpBg/TextHp")
            local curEnergy = FishingUtils.GetFishCardEnergyNum(cardId)
            local maxEnergy = FishingUtils.GetFishCardMaxEnergyNum(cardDojo.cardId)
            --CfUtils.FillText(textHpGo, curEnergy.."/"..maxEnergy)
            CfUtils.FillText(textHpGo, curEnergy)

            hpImageGo.fillAmount = curEnergy/maxEnergy

            local whiteFilledGo = cardParGo.transform:Find("HpStrength/HpBg/whiteFilled"):GetComponent(typeof(CS.UnityEngine.UI.Image))
            whiteFilledGo.fillAmount = curEnergy/maxEnergy

            if bufferData then
                local curNum = 0
                for k, v in pairs(bufferData) do
                    if checkNumber(v.cardId) == checkNumber(cardId) then
                        curNum = checkNumber(v.num)
                        break
                    end
                end 
                hpImageGo.fillAmount = curNum/maxEnergy
            end
        end
    else
        if ind > 1 then
            --上一级解锁没
            local isUnlockLast = FishingUtils.IsUnlockTeamPosByQueueAndCol(self._queueId, ind - 1)
            KTool.SetActive(go.transform:Find("Lock/Text"), isUnlockLast)

            if isUnlockLast then
                CfUtils.FillText(go.transform:Find("Lock/Text"), errStr)
            end
        else
            KTool.SetActive(go.transform:Find("Lock/Text"), true)
            CfUtils.FillText(go.transform:Find("Lock/Text"), errStr)
        end
    end
end

function UIFishPoolHangUpQueueNode:RefreshSelectActive(isTrue)
    KTool.SetActive(self.Select, isTrue)
end

--选择人物
function UIFishPoolHangUpQueueNode:OnBtnChooseCard(pos)
    local isUnlock, errStr = FishingUtils.IsUnlockTeamPosByQueueAndCol(self._queueId, pos)
    if not isUnlock then
        GameUtils.Toast(errStr)
        return
    end
    local isBusy = FishingUtils.IsHangeUpQueueHasTask(self._queueId)
    if isBusy then
        GameUtils.Toast(localize("挂机中无法替换"))
        return
    end
    UIModule.OpenDialog({id = Constants.UITypeIds.UIFightTeamCardChoose, parameters = {chooseCardStatu = Constants.ChooseCardStatus.FishHangeUp, queueId = self._queueId}}, {
        { id = Constants.UITypeIds.UIFishPoolHangUpDialog}
    })
end

function UIFishPoolHangUpQueueNode:OnBtnChooseQueue(isTrue)
    local isUnlock = FishingUtils.IsUnlockQueueById(self._queueId)
    if not isUnlock then
        GameUtils.Toast(localize("该队列未解锁"))
        return
    end
    if self._cb then 
        self._cb()
    end
end

function UIFishPoolHangUpQueueNode:OnFishHangUpTimeDown()
    self:FillTaskInfo()
end

function UIFishPoolHangUpQueueNode:OnDestroy()
    Events.RemoveListener(Constants.EventNames.FishHangUpTimeDown, self.EventFishHangUpTimeDown)
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIFishPoolHangUpQueueNode
